// Junta o estado do site (offers.json) com o das últimas execuções do
// GitHub Actions e monta um relatório curto. Roda na nuvem: chega mesmo se
// o PC estiver desligado — e é justamente aí que o Actions é quem publica.
const CONFIG = { admin_chat_id: '' };   // preencha (mesmo do workflow 01)

const site = $('Ofertas do site').first().json || {};
const runs = ($('Execuções do GitHub Actions').first().json || {}).workflow_runs || [];

const produtos = site.products || [];
const atualizado = site.updated_at ? new Date(site.updated_at) : null;
const horasParado = atualizado ? Math.round((Date.now() - atualizado.getTime()) / 3600000) : null;

const ultimas = runs.slice(0, 5);
const falhas = ultimas.filter(r => r.conclusion && r.conclusion !== 'success');
const brl = v => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');

const top = [...produtos]
  .sort((a, b) => (b.desconto_pct || 0) - (a.desconto_pct || 0))
  .slice(0, 3)
  .map(p => `• ${p.titulo.slice(0, 50)} — ${brl(p.preco)} (${Math.round(p.desconto_pct || 0)}% OFF)`)
  .join('\n') || '• (nenhuma oferta no site)';

// Sinais de problema viram a PRIMEIRA linha do relatório. Um relatório que
// começa com números bonitos e esconde a falha lá embaixo não é lido.
const problemas = [];
if (horasParado !== null && horasParado >= 6) {
  problemas.push(`🔴 Site sem atualizar há ${horasParado}h — pipeline pode estar parado.`);
}
if (falhas.length) {
  problemas.push(`🔴 ${falhas.length} de ${ultimas.length} execuções do GitHub Actions falharam.`);
}
if (!produtos.length) problemas.push('🔴 Nenhuma oferta publicada no site.');

const texto =
  `📊 <b>Relatório diário — Bot Ofertas</b>\n` +
  (problemas.length ? `\n${problemas.join('\n')}\n` : `\n🟢 Tudo funcionando.\n`) +
  `\n<b>Site</b>: ${produtos.length} oferta(s) publicadas` +
  (horasParado !== null ? ` · atualizado há ${horasParado}h` : '') +
  `\n<b>GitHub Actions</b>: ${ultimas.map(r => r.conclusion === 'success' ? '✅' : '❌').join(' ') || '—'}` +
  `\n\n<b>Melhores ofertas agora</b>\n${top}` +
  `\n\n🔗 https://bot-ofertas.github.io`;

return [{ json: { texto, chat_id: CONFIG.admin_chat_id, problemas: problemas.length } }];
